class Solution:
    def minimumPartition(self, s: str, k: int) -> int:
        n = len(s)
        f = [inf] * (n + 1)
        f[n] = 0
        for i in range(n - 1, -1, -1):
            v = 0
            for j in range(i, n):
                v = v * 10 + int(s[j])
                if v > k:
                    break
                f[i] = min(f[i], f[j + 1])
            f[i] += 1
        return f[0] if f[0] < inf else -1

class Solution {
    public int minimumPartition(String s, int k) {
        int n = s.length();
        int inf = 1 << 30;
        int[] f = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            f[i] = inf;
        }
        for (int i = n - 1; i >= 0; --i) {
            long v = 0;
            for (int j = i; j < n; ++j) {
                v = v * 10 + (s.charAt(j) - '0');
                if (v > k) {
                    break;
                }
                f[i] = Math.min(f[i], f[j + 1]);
            }
            ++f[i];
        }
        return f[0] < inf ? f[0] : -1;
    }
}

